use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::os::unix::fs::symlink;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

mod args;
mod conf;
mod install;
mod shell;

const VERSION: &str = "1.54.0";

fn main() -> ExitCode {
    let raw: Vec<String> = env::args().collect();

    let parsed = match args::parse(&raw[1..]) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            return ExitCode::from(2);
        }
    };

    // --help -> print help and may continue to --version output
    let mut any_info = false;
    if parsed.help {
        help::print();
        any_info = true;
    }
    if parsed.version {
        println!("broot {}", VERSION);
        any_info = true;
    }
    if any_info {
        return ExitCode::SUCCESS;
    }

    if let Some(sh) = &parsed.print_shell_function {
        match shell::script_for(sh) {
            Some(s) => {
                print!("{}", s);
                return ExitCode::SUCCESS;
            }
            None => {
                println!("Unknown shell: {}", sh);
                return ExitCode::SUCCESS;
            }
        }
    }

    if let Some(path) = &parsed.write_default_conf {
        match conf::write_default(Path::new(path)) {
            Ok(()) => return ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("Error writing default conf: {}", e);
                return ExitCode::from(1);
            }
        }
    }

    if let Some(state) = &parsed.set_install_state {
        install::set_state(state);
        return ExitCode::SUCCESS;
    }

    if parsed.install {
        install::do_install(true);
        return ExitCode::SUCCESS;
    }

    // Interactive installation prompt when not yet installed
    if !install::is_installed() && !install::is_refused() {
        install::prompt_and_install();
    }

    // TUI not supported in this reimplementation
    eprintln!("Termimad Error : IO error: No such device or address (os error 6)");
    ExitCode::from(1)
}

mod help {
    pub fn print() {
        print!("{}", HELP_TEXT);
    }
    const HELP_TEXT: &str = include_str!("help_text.txt");
}
MAIN_EOF
echo OK

