// Custom argument parser mimicking broot's CLI surface.

#[derive(Default, Debug)]
pub struct ParsedArgs {
    pub help: bool,
    pub version: bool,
    pub install: bool,
    pub print_shell_function: Option<String>,
    pub write_default_conf: Option<String>,
    pub set_install_state: Option<String>,
    pub color: String, // "auto" / "yes" / "no"
    pub cmd: Option<String>,
    pub conf: Option<String>,
    pub height: Option<String>,
    pub outcmd: Option<String>,
    pub verb_output: Option<String>,
    pub listen: Option<String>,
    pub listen_auto: bool,
    pub get_root: bool,
    pub send: Option<String>,
    pub root: Option<String>,

    // simple flags (not all are used by us, but we parse them for fidelity)
    pub flag_dates: bool,
    pub flag_no_dates: bool,
    pub flag_only_folders: bool,
    pub flag_no_only_folders: bool,
    pub flag_show_root_fs: bool,
    pub flag_show_git_info: bool,
    pub flag_no_show_git_info: bool,
    pub flag_git_status: bool,
    pub flag_hidden: bool,
    pub flag_no_hidden: bool,
    pub flag_git_ignored: bool,
    pub flag_no_git_ignored: bool,
    pub flag_permissions: bool,
    pub flag_no_permissions: bool,
    pub flag_sizes: bool,
    pub flag_no_sizes: bool,
    pub flag_sort_by_count: bool,
    pub flag_sort_by_date: bool,
    pub flag_sort_by_size: bool,
    pub flag_sort_by_type: bool,
    pub flag_sort_by_type_dirs_first: bool,
    pub flag_sort_by_type_dirs_last: bool,
    pub flag_no_sort: bool,
    pub flag_tree: bool,
    pub flag_no_tree: bool,
    pub flag_whale_spotting: bool,
    pub flag_no_whale_spotting: bool,
    pub flag_trim_root: bool,
    pub flag_no_trim_root: bool,
    pub max_depth: Option<String>,
}

pub fn parse(argv: &[String]) -> Result<ParsedArgs, String> {
    let mut p = ParsedArgs::default();
    p.color = "auto".to_string();

    let mut i = 0;
    let mut dashdash = false;
    let mut positional: Vec<String> = Vec::new();
    while i < argv.len() {
        let a = &argv[i];
        if dashdash {
            positional.push(a.clone());
            i += 1;
            continue;
        }
        if a == "--" {
            dashdash = true;
            i += 1;
            continue;
        }
        // long options with =value form
        let (name, inline): (&str, Option<&str>) = if a.starts_with("--") {
            if let Some(eq) = a.find('=') {
                (&a[..eq], Some(&a[eq + 1..]))
            } else {
                (&a[..], None)
            }
        } else {
            (&a[..], None)
        };
        // Helper to fetch the option value (either inline after `=` or next arg)
        let get_val = |i: &mut usize, inline: Option<&str>| -> Result<String, String> {
            if let Some(v) = inline {
                Ok(v.to_string())
            } else {
                *i += 1;
                if *i >= argv.len() {
                    Err(format!(
                        "error: a value is required for '{} <{}>' but none was supplied",
                        name, value_name_for(name)
                    ))
                } else {
                    Ok(argv[*i].clone())
                }
            }
        };

        match name {
            "--help" => p.help = true,
            "--version" => p.version = true,
            "--install" => p.install = true,
            "--listen-auto" => p.listen_auto = true,
            "--get-root" => p.get_root = true,
            "--show-root-fs" => p.flag_show_root_fs = true,
            "--git-status" => p.flag_git_status = true,
            "--sort-by-count" => p.flag_sort_by_count = true,
            "--sort-by-date" => p.flag_sort_by_date = true,
            "--sort-by-size" => p.flag_sort_by_size = true,
            "--sort-by-type" => p.flag_sort_by_type = true,
            "--sort-by-type-dirs-first" => p.flag_sort_by_type_dirs_first = true,
            "--sort-by-type-dirs-last" => p.flag_sort_by_type_dirs_last = true,
            "--no-sort" => p.flag_no_sort = true,
            "--tree" => p.flag_tree = true,
            "--no-tree" => p.flag_no_tree = true,

            "-d" | "--dates" => p.flag_dates = true,
            "-D" | "--no-dates" => p.flag_no_dates = true,
            "-f" | "--only-folders" => p.flag_only_folders = true,
            "-F" | "--no-only-folders" => p.flag_no_only_folders = true,
            "-g" | "--show-git-info" => p.flag_show_git_info = true,
            "-G" | "--no-show-git-info" => p.flag_no_show_git_info = true,
            "-h" | "--hidden" => p.flag_hidden = true,
            "-H" | "--no-hidden" => p.flag_no_hidden = true,
            "-i" | "--git-ignored" => p.flag_git_ignored = true,
            "-I" | "--no-git-ignored" => p.flag_no_git_ignored = true,
            "-p" | "--permissions" => p.flag_permissions = true,
            "-P" | "--no-permissions" => p.flag_no_permissions = true,
            "-s" | "--sizes" => p.flag_sizes = true,
            "-S" | "--no-sizes" => p.flag_no_sizes = true,
            "-w" | "--whale-spotting" => p.flag_whale_spotting = true,
            "-W" | "--no-whale-spotting" => p.flag_no_whale_spotting = true,
            "-t" | "--trim-root" => p.flag_trim_root = true,
            "-T" | "--no-trim-root" => p.flag_no_trim_root = true,

            "--outcmd" => p.outcmd = Some(get_val(&mut i, inline)?),
            "-c" | "--cmd" => p.cmd = Some(get_val(&mut i, inline)?),
            "--verb-output" => p.verb_output = Some(get_val(&mut i, inline)?),
            "--conf" => p.conf = Some(get_val(&mut i, inline)?),
            "--height" => p.height = Some(get_val(&mut i, inline)?),
            "--max-depth" => p.max_depth = Some(get_val(&mut i, inline)?),
            "--listen" => p.listen = Some(get_val(&mut i, inline)?),
            "--send" => p.send = Some(get_val(&mut i, inline)?),
            "--write-default-conf" => {
                p.write_default_conf = Some(get_val(&mut i, inline)?)
            }
            "--print-shell-function" => {
                p.print_shell_function = Some(get_val(&mut i, inline)?)
            }
            "--color" => {
                let v = get_val(&mut i, inline)?;
                match v.as_str() {
                    "auto" | "yes" | "no" => p.color = v,
                    _ => {
                        return Err(format!(
                            "error: invalid value '{}' for '--color <color>'\n  [possible values: auto, yes, no]",
                            v
                        ))
                    }
                }
            }
            "--set-install-state" => {
                let v = get_val(&mut i, inline)?;
                match v.as_str() {
                    "undefined" | "refused" | "installed" => {
                        p.set_install_state = Some(v)
                    }
                    _ => {
                        return Err(format!(
                            "error: invalid value '{}' for '--set-install-state <state>'\n  [possible values: undefined, refused, installed]",
                            v
                        ))
                    }
                }
            }
            other => {
                if other.starts_with('-') && !(positional.is_empty() && other == "-") {
                    return Err(format!(
                        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [ROOT]",
                        other, other, other
                    ));
                }
                positional.push(a.clone());
            }
        }
        i += 1;
    }

    if positional.len() > 1 {
        return Err(format!(
            "error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [ROOT]",
            positional[1]
        ));
    }
    if let Some(root) = positional.into_iter().next() {
        p.root = Some(root);
    }
    Ok(p)
}

fn value_name_for(long: &str) -> &'static str {
    match long {
        "--print-shell-function" => "shell",
        "--write-default-conf" => "path",
        "--outcmd" => "path",
        "--verb-output" => "verb-output",
        "--cmd" | "-c" => "cmd",
        "--conf" => "paths",
        "--color" => "color",
        "--height" => "height",
        "--max-depth" => "MAX_DEPTH",
        "--set-install-state" => "state",
        "--listen" => "socket",
        "--send" => "socket",
        _ => "value",
    }
}
ARGS_EOF
echo OK

