// Install / set-install-state logic
use std::env;
use std::fs;
use std::io::{self, BufRead, Write};
use std::os::unix::fs::symlink;
use std::path::{Path, PathBuf};

const BASH_SCRIPT: &str = include_str!("shells/bash.txt");
const FISH_SCRIPT: &str = include_str!("shells/fish.txt");

const INSTALLED_FILE: &str = "installed-v4";
const REFUSED_FILE: &str = "refused";
const INSTALLED_CONTENT: &str = "\nThis file tells broot the installation of the br function was done.\nIf there's a problem and you want to install it again run\n    broot -- install\n";
const REFUSED_CONTENT: &str = "\nThis file tells broot you refused the installation of the companion shell function.\nIf you want to install it run\n    broot -- install\n";

// ANSI helpers mimicking broot's termimad output style
fn code(s: &str) -> String { // `code` style: bg 234, fg 250
    format!("\x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m", s)
}
fn ital_magenta(s: &str) -> String { // *italic-magenta* for emphasized names
    format!("\x1b[38;5;13m\x1b[3m{}\x1b[0m", s)
}
fn bold(s: &str) -> String {
    format!("\x1b[1m{}\x1b[0m", s)
}

fn config_dir() -> PathBuf {
    if let Ok(v) = env::var("XDG_CONFIG_HOME") {
        if !v.is_empty() {
            return PathBuf::from(v).join("broot");
        }
    }
    let home = env::var("HOME").unwrap_or_default();
    PathBuf::from(home).join(".config").join("broot")
}
fn data_dir() -> PathBuf {
    if let Ok(v) = env::var("XDG_DATA_HOME") {
        if !v.is_empty() {
            return PathBuf::from(v).join("broot");
        }
    }
    let home = env::var("HOME").unwrap_or_default();
    PathBuf::from(home).join(".local").join("share").join("broot")
}
fn home_dir() -> PathBuf {
    PathBuf::from(env::var("HOME").unwrap_or_default())
}

fn launcher_config_dir() -> PathBuf { config_dir().join("launcher") }
fn launcher_data_dir() -> PathBuf { data_dir().join("launcher") }

pub fn is_installed() -> bool {
    launcher_config_dir().join(INSTALLED_FILE).exists()
}
pub fn is_refused() -> bool {
    launcher_config_dir().join(REFUSED_FILE).exists()
}

pub fn set_state(state: &str) {
    let lc = launcher_config_dir();
    let installed = lc.join(INSTALLED_FILE);
    let refused = lc.join(REFUSED_FILE);
    match state {
        "installed" => {
            if refused.exists() {
                println!("Removing {}.", code(refused.to_str().unwrap_or_default()));
                let _ = fs::remove_file(&refused);
            }
            if !installed.exists() {
                let _ = fs::create_dir_all(&lc);
                let _ = fs::write(&installed, INSTALLED_CONTENT);
            }
        }
        "refused" => {
            if installed.exists() {
                println!("Removing {}.", code(installed.to_str().unwrap_or_default()));
                let _ = fs::remove_file(&installed);
            }
            if !refused.exists() {
                let _ = fs::create_dir_all(&lc);
                let _ = fs::write(&refused, REFUSED_CONTENT);
            }
        }
        "undefined" => {
            if installed.exists() {
                println!("Removing {}.", code(installed.to_str().unwrap_or_default()));
                let _ = fs::remove_file(&installed);
            }
            if refused.exists() {
                println!("Removing {}.", code(refused.to_str().unwrap_or_default()));
                let _ = fs::remove_file(&refused);
            }
        }
        _ => {}
    }
}

pub fn prompt_and_install() {
    // Print the prompt.
    println!();
    println!("{} should be launched using a shell function.", bold("Broot"));
    println!("This function most notably makes it possible to {}", code("cd"));
    println!("from inside broot");
    println!(
        "(see {} for ",
        ital_magenta("https://dystroy.org/broot/install-br/")
    );
    println!("explanations).");
    println!();
    print!("Can I install it now? [{}/n]\n", bold("Y"));

    // Read one line from stdin; default yes
    let stdin = io::stdin();
    let mut line = String::new();
    let _ = stdin.lock().read_line(&mut line);
    let answer = line.trim().to_ascii_lowercase();
    let yes = answer.is_empty() || answer == "y" || answer == "yes";
    if yes {
        do_install(false);
    } else {
        mark_refused();
        println!();
        println!("You refused the installation (for now).");
        println!("You can still used {} but some features won't ", code("broot"));
        println!("be available.");
        println!("If you want the {} shell function, you may either", code("br"));
        println!("{} do {}", mid_bullet(), code("broot --install"));
        println!("{} install the various pieces yourself", mid_bullet());
        println!(
            "(see {} for ",
            ital_magenta("https://dystroy.org/broot/install-br/")
        );
        println!("details).");
    }
}

fn mid_bullet() -> String { format!("\x1b[38;5;240m\u{2022}\x1b[39m") }

pub fn do_install(clean_reinstall: bool) {
    if clean_reinstall {
        println!("You requested a clean (re)install.");
        remove_launchers_for_clean();
    }
    install_bash_like("bash", ".bashrc");
    install_bash_like("zsh", ".zshrc");
    install_fish();
    mark_installed();
    println!();
    println!("The {} function has been successfully installed.", bold("br"));
    println!("You may have to restart your shell or source your ");
    println!("shell init files.");
    println!(
        "Afterwards, you should start broot with {} in ",
        code("br")
    );
    println!("order to use its full power.");
}

fn remove_launchers_for_clean() {
    // Remove install state files first if present, and any existing launcher scripts
    let lc = launcher_config_dir();
    let ld = launcher_data_dir();
    let installed = lc.join(INSTALLED_FILE);
    if installed.exists() {
        println!("Removing {}.", code(installed.to_str().unwrap_or_default()));
        let _ = fs::remove_file(&installed);
    }
    let refused = lc.join(REFUSED_FILE);
    if refused.exists() {
        println!("Removing {}.", code(refused.to_str().unwrap_or_default()));
        let _ = fs::remove_file(&refused);
    }

    for sh_name in ["bash", "zsh"] {
        let data_script = ld.join(sh_name).join("1");
        if data_script.exists() {
            println!("Removing {}.", code(data_script.to_str().unwrap_or_default()));
            let _ = fs::remove_file(&data_script);
        }
    }
    // For the symlink under config/broot/launcher/<sh>/br
    for sh_name in ["bash", "zsh"] {
        let link = lc.join(sh_name).join("br");
        if link.exists() || is_symlink(&link) {
            // Do not print this removal; the "Removing link" is covered by the subsequent re-link step
        }
    }
}

fn is_symlink(p: &Path) -> bool {
    fs::symlink_metadata(p).map(|m| m.file_type().is_symlink()).unwrap_or(false)
}

fn install_bash_like(sh_name: &str, rc_basename: &str) {
    let rc = home_dir().join(rc_basename);
    if !rc.exists() {
        return;
    }
    let ld = launcher_data_dir();
    let script_dir = ld.join(sh_name);
    let _ = fs::create_dir_all(&script_dir);
    let script_path = script_dir.join("1");
    println!(
        "Writing {} shell function in {}.",
        ital_magenta("br"),
        code(script_path.to_str().unwrap_or_default())
    );
    let _ = fs::write(&script_path, BASH_SCRIPT);

    let lc = launcher_config_dir();
    let link_dir = lc.join(sh_name);
    let _ = fs::create_dir_all(&link_dir);
    let link_path = link_dir.join("br");
    if is_symlink(&link_path) || link_path.exists() {
        println!("Removing {}.", code(link_path.to_str().unwrap_or_default()));
        let _ = fs::remove_file(&link_path);
    }
    println!(
        "Creating link from {} to {}.",
        code(link_path.to_str().unwrap_or_default()),
        code(script_path.to_str().unwrap_or_default())
    );
    let _ = symlink(&script_path, &link_path);

    // Patch rc if not already patched
    let needle = format!("source {}", link_path.display());
    let rc_text = fs::read_to_string(&rc).unwrap_or_default();
    if rc_text.contains(&needle) {
        println!(
            "{} already patched, no change made.",
            code(rc.to_str().unwrap_or_default())
        );
    } else {
        let mut new = rc_text;
        if !new.ends_with('\n') {
            new.push('\n');
        }
        new.push('\n');
        new.push_str(&needle);
        new.push('\n');
        let _ = fs::write(&rc, new);
        let source_kw = if sh_name == "zsh" { "exec zsh" } else { "source " };
        if sh_name == "zsh" {
            println!(
                "{} successfully patched, you can make the function immediately available with {}",
                code(rc.to_str().unwrap_or_default()),
                code("exec zsh")
            );
        } else {
            println!(
                "{} successfully patched, you can make the function immediately available with {}{}",
                code(rc.to_str().unwrap_or_default()),
                code("source "),
                code(rc.to_str().unwrap_or_default())
            );
        }
    }
}

fn install_fish() {
    let fish_cfg = home_dir().join(".config").join("fish");
    if !fish_cfg.exists() {
        return;
    }
    let ld = launcher_data_dir();
    let script_dir = ld.join("fish");
    let _ = fs::create_dir_all(&script_dir);
    let script_path = script_dir.join("br.fish");
    println!(
        "Writing {} shell function in {}.",
        ital_magenta("br"),
        code(script_path.to_str().unwrap_or_default())
    );
    let _ = fs::write(&script_path, FISH_SCRIPT);
    let func_dir = fish_cfg.join("functions");
    let _ = fs::create_dir_all(&func_dir);
    let link_path = func_dir.join("br.fish");
    if is_symlink(&link_path) || link_path.exists() {
        println!("Removing {}.", code(link_path.to_str().unwrap_or_default()));
        let _ = fs::remove_file(&link_path);
    }
    println!(
        "Creating link from {} to {}.",
        code(link_path.to_str().unwrap_or_default()),
        code(script_path.to_str().unwrap_or_default())
    );
    let _ = symlink(&script_path, &link_path);
}

fn mark_installed() {
    let lc = launcher_config_dir();
    let _ = fs::create_dir_all(&lc);
    let _ = fs::write(lc.join(INSTALLED_FILE), INSTALLED_CONTENT);
    let _ = fs::remove_file(lc.join(REFUSED_FILE));
}

fn mark_refused() {
    let lc = launcher_config_dir();
    let _ = fs::create_dir_all(&lc);
    let _ = fs::write(lc.join(REFUSED_FILE), REFUSED_CONTENT);
    let _ = fs::remove_file(lc.join(INSTALLED_FILE));
}
EOF
