    conf::ensure_default();

    // If a ROOT path was provided and it doesn't exist, emit IO error and exit 1
    if let Some(root) = &parsed.root {
        let pb = std::path::PathBuf::from(root);
        if !pb.exists() {
            println!("IO Error : No such file or directory (os error 2)");
            return ExitCode::from(1);
        }
